svg.script:
var ns = "http://www.w3.org/2000/svg";
var dt = document.getElementById("dt");
var db = document.getElementById("db");
var phases = [].slice.call(document.querySelectorAll(".n"));
var phaseConnectors = [].slice.call(document.querySelectorAll(".phase-connector"));
var nextPhaseToUnlock = 0;

phases.forEach(function(phase, index) {
  if (index > 0) phase.classList.add("phase-hidden");
});
phaseConnectors.forEach(function(connector, index) {
  if (index > 0) connector.classList.add("phase-hidden");
});

function wrap(t, w) {
  while (t.firstChild) t.removeChild(t.firstChild);
  var words = t.getAttribute("data-x").split(" "), line = "";
  var tsp = document.createElementNS(ns, "tspan");
  tsp.setAttribute("x", t.getAttribute("x"));
  tsp.setAttribute("dy", "0");
  t.appendChild(tsp);

  words.forEach(function(wd) {
    if (wd === "•" && line) {
      tsp = document.createElementNS(ns, "tspan");
      tsp.setAttribute("x", t.getAttribute("x"));
      tsp.setAttribute("dy", "26");
      t.appendChild(tsp);
      line = wd;
      tsp.textContent = line;
      return;
    }
    var test = line ? line + " " + wd : wd;
    tsp.textContent = test;
    if (tsp.getComputedTextLength() > w && line) {
      tsp.textContent = line;
      tsp = document.createElementNS(ns, "tspan");
      tsp.setAttribute("x", t.getAttribute("x"));
      tsp.setAttribute("dy", "26");
      t.appendChild(tsp);
      line = wd;
      tsp.textContent = wd;
    } else {
      line = test;
    }
  });
}

function show(t, b) {
  dt.textContent = t;
  db.setAttribute("data-x", b);
  wrap(db, 1090);
}

var all = [].slice.call(document.querySelectorAll(".k"));
all.forEach(function(g) {
  function go() {
    var phaseIndex = phases.indexOf(g);
    if (phaseIndex === nextPhaseToUnlock && phaseIndex < phases.length - 1) {
      phases[phaseIndex + 1].classList.remove("phase-hidden");
      if (phaseConnectors[phaseIndex + 1]) {
        phaseConnectors[phaseIndex + 1].classList.remove("phase-hidden");
      }
      nextPhaseToUnlock++;
    }
    all.forEach(function(o) {
      o.classList.remove("sel");
      o.setAttribute("aria-pressed", "false");
    });
    g.classList.add("sel");
    g.setAttribute("aria-pressed", "true");
    show(g.getAttribute("data-t"), g.getAttribute("data-d"));
  }
  g.addEventListener("click", go);
  g.addEventListener("keydown", function(e) {
    if (e.key === "Enter" || e.key === " ") {
      e.preventDefault();
      go();
    }
  });
});

// Affichage initial
show(dt.getAttribute("data-t0"), db.getAttribute("data-x0"));

var roadmapRoot = document.documentElement;
var roadmapGuide = document.getElementById("roadmap-guide");
var detailsButton = document.querySelector(".roadmap-details-button");
var backButton = document.querySelector(".roadmap-back");
var roadmapChoices = [].slice.call(document.querySelectorAll(".roadmap-choice"));
var guideDetailTitle = document.getElementById("guide-detail-title");
var guideDetailCopy = document.getElementById("guide-detail-copy");
var loopSequenceTimer = 0;
var loopSequenceId = 0;
var loopArrow = document.getElementById("loop-arrow-traveler");
var loopArrowMotion = document.getElementById("loop-arrow-motion");
var loopSteps = [
  {path:"M1052 244C1074 244 1085 269 1085 307", icon:"loop-icon-data"},
  {path:"M1085 385V507", icon:"loop-icon-products"},
  {path:"M1016 546H948", icon:"loop-icon-revenue"},
  {path:"M876 507V385", icon:"loop-icon-treasury"},
  {path:"M876.5 307C877 279 890 252 908 244", icon:"loop-icon-community"}
];
function bindAction(element, action) {
  element.addEventListener("click", action);
  element.addEventListener("keydown", function(event) {
    if (event.key === "Enter" || event.key === " ") { event.preventDefault(); action(); }
  });
}
bindAction(detailsButton, function() {
  roadmapRoot.classList.add("roadmap-details");
  loopSequenceId++;
  window.clearTimeout(loopSequenceTimer);
  loopArrow.setAttribute("opacity", "0");
  document.querySelectorAll(".loop-destination-icon").forEach(function(icon) { icon.classList.remove("is-blinking"); });
  phases.forEach(function(phase) { phase.classList.remove("phase-hidden"); });
  phaseConnectors.forEach(function(connector) { connector.classList.remove("phase-hidden"); });
});
bindAction(backButton, function() { roadmapRoot.classList.remove("roadmap-details"); });
function runLoop() {
  if (window.matchMedia("(prefers-reduced-motion: reduce)").matches) return;
  loopSequenceId++;
  var sequence = loopSequenceId;
  window.clearTimeout(loopSequenceTimer);
  loopArrow.setAttribute("opacity", "0");
  document.querySelectorAll(".loop-destination-icon").forEach(function(icon) { icon.classList.remove("is-blinking"); });
  document.querySelectorAll(".loop-copy").forEach(function(copy) { copy.classList.remove("is-revealed"); });
  function advance(index) {
    if (sequence !== loopSequenceId) return;
    if (index >= loopSteps.length) { loopArrow.setAttribute("opacity", "0"); return; }
    var step = loopSteps[index];
    loopArrowMotion.setAttribute("path", step.path);
    loopArrow.setAttribute("opacity", "1");
    loopArrowMotion.beginElement();
    loopSequenceTimer = window.setTimeout(function() {
      loopArrow.setAttribute("opacity", "0");
      var icon = document.getElementById(step.icon);
      icon.classList.add("is-blinking");
      icon.parentNode.querySelector(".loop-copy").classList.add("is-revealed");
      loopSequenceTimer = window.setTimeout(function() {
        icon.classList.remove("is-blinking");
        advance(index + 1);
      }, 2000);
    }, 800);
  }
  document.getElementById("loop-icon-community").parentNode.querySelector(".loop-copy").classList.add("is-revealed");
  loopSequenceTimer = window.setTimeout(function() { advance(0); }, 500);
}
roadmapChoices.forEach(function(choice) {
  bindAction(choice, function() {
    roadmapChoices.forEach(function(item) {
      item.classList.remove("sel");
      item.setAttribute("aria-pressed", String(item === choice));
    });
    choice.classList.add("sel");
    guideDetailTitle.textContent = choice.getAttribute("data-guide-title");
    guideDetailCopy.textContent = choice.getAttribute("data-guide-copy");
    if (choice.classList.contains("loop-choice") && !window.matchMedia("(prefers-reduced-motion: reduce)").matches) runLoop();
  });
});
bindAction(document.querySelector(".roadmap-run-loop"), runLoop);
